import {STORAGE_KEY,products,audiences,preparationSteps,lockedStatuses,seedState,restore,newCampaign,defaultBrief,validateBrief,transition,approveReady} from './state.js';
import {BACKUP_KEY,inspectSavedLanguage,appendLanguageBackup} from './language.js';
const $=s=>document.querySelector(s);
const escape=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
import {number,currency,count,shortDate} from './format.js';
const icon=(name,size=20)=>{const paths={grid:'M3 3h7v7H3z M14 3h7v7h-7z M3 14h7v7H3z M14 14h7v7h-7z',mail:'M3 5h18v14H3z M3 5l9 7 9-7',check:'M5 12l4 4L19 6',chart:'M4 20V12 M10 20V4 M16 20V8 M22 20H2',layers:'M12 3l10 6-10 6L2 9z M2 14l10 6 10-6',plus:'M12 5v14 M5 12h14',clock:'M12 8v5l3 2 M21 12a9 9 0 1 1-18 0 9 9 0 0 1 18 0',file:'M5 3h9l5 5v13H5z M14 3v6h5 M8 13h8 M8 17h5',play:'M8 4l12 8-12 8z',reset:'M3 10a9 9 0 1 1 2 8 M3 4v6h6',chevron:'M9 5l7 7-7 7',back:'M15 5l-7 7 7 7',close:'M6 6l12 12 M18 6 6 18',shield:'M12 2l9 4v6c0 5-9 10-9 10S3 17 3 12V6z M8 12l3 3 5-6',spark:'M12 3l2.5 6.5L21 12l-6.5 2.5L12 21l-2.5-6.5L3 12l6.5-2.5z',users:'M16 21v-3a4 4 0 0 0-4-4H5a4 4 0 0 0-4 4v3 M12 6a4 4 0 1 1-8 0 4 4 0 0 1 8 0 M22 21v-3a4 4 0 0 0-3-4 M16 2a4 4 0 0 1 0 8',info:'M12 10v7 M12 7h.01 M21 12a9 9 0 1 1-18 0 9 9 0 0 1 18 0',pause:'M8 4v16 M16 4v16',external:'M14 3h7v7 M21 3l-9 9 M10 3H3v18h18v-7'};return `<svg width="${size}" height="${size}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${paths[name]||paths.file}"/></svg>`;};
const labels={draft:'Draft',preparing:'Preparing',prep_paused:'Preparation paused',prep_error:'Data issue',review:'Needs review',approved:'Approved',scheduled:'Reserved',running:'Running',delivery_paused:'Execution paused',retry_wait:'Backoff',needs_attention:'Needs attention',completed:'Completed'};
const badge=c=>`<span class="badge status-${c.status}">${labels[c.status]}</span>`;
const button=(text,action,cls='secondary',attrs='',ico='')=>`<button class="btn ${cls}" data-action="${action}" ${attrs}>${ico?icon(ico,17):''}${text}</button>`;
let state,legacyRaw=null,hasLanguageBackup=false;try{const raw=localStorage.getItem(STORAGE_KEY);const inspected=inspectSavedLanguage(raw);legacyRaw=inspected.blocked?raw:null;state=legacyRaw?seedState():restore(raw);hasLanguageBackup=!!localStorage.getItem(BACKUP_KEY);}catch{state=seedState();}
const ui={filter:'all',search:'',checks:{},modal:null,lastFocus:null,menu:false,toastTimer:null,storageError:false};
let route=parseRoute();
function parseRoute(){const [view,id,tab]=location.hash.slice(1).split('/');return ['campaign','review','execution','capabilities'].includes(view)?{view,id,tab:tab||'brief'}:{view:'overview'};}
function persist(){if(legacyRaw)return;try{localStorage.setItem(STORAGE_KEY,JSON.stringify(state));}catch{ui.storageError=true;}}
function current(){return state.campaigns.find(c=>c.id===route.id);}
function toast(message){$('#toast').textContent=message;$('#toast').classList.add('visible');clearTimeout(ui.toastTimer);ui.toastTimer=setTimeout(()=>$('#toast').classList.remove('visible'),4200);}
function go(hash){if(location.hash===`#${hash}`){route=parseRoute();render();}else{location.hash=hash;}window.scrollTo(0,0);ui.menu=false;}
window.addEventListener('hashchange',()=>{ui.menu=false;route=parseRoute();render();});
const nav=(text,view,ico,extra='')=>`<a href="#${view}" class="nav-item ${route.view===view||(view==='overview'&&route.view==='campaign')?'active':''}">${icon(ico)}<span>${text}</span>${extra}</a>`;
function shell(content){return `<a class="skip-link" href="#main">Skip to workspace</a><aside class="sidebar ${ui.menu?'open':''}"><a class="wordmark" href="#overview"><span class="brand-icon">R</span>relay<span class="brand-dot">.</span></a><div class="workspace"><span class="store-mark">V</span><div><strong>Vela Studio</strong><small>Marketing workspace</small></div></div><div class="nav-label">WORKSPACE</div><nav aria-label="Main navigation">${nav('Campaigns','overview','grid')}${nav('Review Queue','review','shield',`<span class="nav-count">${state.campaigns.filter(c=>c.status==='review').length}</span>`)}${nav('Execution Log','execution','chart')}${nav('Capabilities','capabilities','layers')}</nav><div class="sidebar-note"><span class="pill">EDM WORKSPACE</span><h3>Good campaigns.<br>Thoughtfully connected.</h3><p>From planning to approval,<br>keep every step in view.</p><a href="#capabilities">Explore product roadmap ${icon('chevron',14)}</a></div><div class="sidebar-bottom"><span class="avatar">VS</span><div><strong>Vela Studio</strong><small>Marketing team</small></div><button class="icon-btn" data-action="about" aria-label="About This Demo">${icon('info',17)}</button></div></aside><div class="app-shell"><header class="topbar"><div class="top-left"><button class="icon-btn mobile-menu" data-action="menu" aria-label="Toggle navigation">${icon('layers')}</button><span class="crumb">Workspace</span><span class="crumb-sep">/</span><strong>${({overview:'Campaigns',campaign:'Campaign Workflow',review:'Review Queue',execution:'Execution Log',capabilities:'Capabilities'})[route.view]}</strong></div><div class="top-actions">${button('Guided tour','guide','quiet','','play')}${button('Reset demo','reset','quiet','','reset')}${button('About this demo','about','quiet','','info')}</div></header>${ui.storageError?'<div class="notice danger">Browser storage is unavailable. Keep this tab open; refreshing will reset the demo.</div>':''}<main id="main" tabindex="-1">${guidePanel()}${content}</main><footer class="footer"><span>Relay · Vela Studio workspace</span><button data-action="about">About This Demo</button></footer></div>`;}

function languageGate(){return pageHead('ENGLISH WORKSPACE','Saved Workspace Needs Review','Your saved workspace contains Chinese or full-width text. Your edits have not been changed.')+`<section class="panel language-gate"><h2>Keep Your Saved Work</h2><p>Download the original workspace before starting with English sample campaigns. A copy will also be retained in this browser. Saved campaign names, drafts, approvals and audit notes are never translated or discarded automatically.</p><div class="send-actions">${button('Download saved workspace','downloadLegacy','secondary','','file')}${button('Start English demo','confirmEnglishDemo','primary','','play')}</div><p class="small-note">The saved data is hidden from the English interface until you choose how to proceed. Your original storage remains unchanged.</p></section>`;}
function downloadJSON(raw,name){const url=URL.createObjectURL(new Blob([raw],{type:'application/json'}));const link=document.createElement('a');link.href=url;link.download=name;link.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('Workspace download requested. No data was changed.');}
function startEnglishDemo(){if(!legacyRaw)return;try{const backup=appendLanguageBackup(legacyRaw,localStorage.getItem(BACKUP_KEY));localStorage.setItem(BACKUP_KEY,backup);if(localStorage.getItem(BACKUP_KEY)!==backup)throw Error('Backup verification failed');const next=seedState();localStorage.setItem(STORAGE_KEY,JSON.stringify(next));state=next;legacyRaw=null;hasLanguageBackup=true;ui.checks={};ui.filter='all';ui.search='';closeModal();go('overview');render();toast('English demo ready. The original workspace is preserved in a downloadable backup.');}catch{toast('Unable to save the backup. Download your workspace first; the original has not been replaced.');}}

function aboutModal(){openModal('About This Demo',`<div class="modal-body about-demo"><span class="badge muted">CLICKABLE FRONTEND · VELA K75 CASE STUDY</span><h3>A Clickable Frontend Prototype</h3><p>Vela Studio, the K75 keyboard, product specifications, prices, inventory, audiences and execution results are fictional examples. The three keyboard images are original local SVG concept illustrations, not photographs of real products or evidence of brand authorisation.</p><p>Preparation uses fixed templates and local scripts. Reservations, sending, rate limits, retries and receipt reconciliation are simulated in this browser. There is no backend, live store, email service or AI model connection. No email is sent. Completed and acknowledged records describe demo state changes only.</p><h3>Capability Boundaries</h3><ul><li><strong>Existing practice:</strong>The team has Blog and EDM generation code and a separate EDM automation project. Repository documentation distinguishes its production MVP, local v0.2 validation and remaining integration work.</li><li><strong>This prototype:</strong>Interactive workflows, version-specific approval, approval withdrawal after edits, execution recovery, campaign isolation and local storage.</li><li><strong>Future plans:</strong>Live connectors, model generation, server-side tasks and permission checks. Blog and listing workflows will support EDM, followed by Amazon and TikTok.</li></ul><p class="small-note">Data stays in this browser. Reset demo restores the sample campaigns. Prototype tests do not establish production delivery or live platform readiness.</p></div>`,`${hasLanguageBackup?button('Download saved workspace backup','downloadLanguageBackup','secondary'):''}${button('Close','closeModal','secondary')}<a class="btn primary" data-action="closeForLink" href="#capabilities">View capability map</a>`);}

function pageHead(kicker,title,description,actions=''){return `<div class="page-heading"><div><div class="eyebrow">${kicker}</div><h1>${title}</h1><p>${description}</p></div><div class="heading-actions">${actions}</div></div>`;}
function overview(){
  const list=state.campaigns.filter(c=>(ui.filter==='all'||(ui.filter==='attention'?['review','needs_attention','prep_error'].includes(c.status):c.status===ui.filter))&&c.brief.name.toLowerCase().includes(ui.search.toLowerCase()));
  const reviews=state.campaigns.filter(c=>c.status==='review').length,active=state.campaigns.filter(c=>!['draft','completed'].includes(c.status)).length;
  const sent=state.campaigns.reduce((n,c)=>n+(c.delivery?.sent||0),0);
  return `${pageHead('MARKETING OPERATIONS','Campaigns','Plan with intent. Prepare with context. Keep people in control.',button('New campaign','new','primary','','plus'))}<div class="overview-grid"><section class="panel overview-hero"><div class="hero-copy"><span class="hero-label">NEW COLLECTION / K75</span><h2>The K75 launch.<br>One coordinated campaign.</h2><p>Introduce the K75. Bring the product story, audience and offer together in one considered launch.</p><div class="hero-actions">${button('Explore the launch flow','guide','primary','','play')}<span>From launch brief to approval and execution</span></div></div><div class="hero-keyboard"><img src="assets/keyboard-graphite.svg" alt="Original Vela K75 Graphite mechanical keyboard concept illustration"><div class="hero-product-label"><span>VELA K75</span><small>75% LAYOUT · GRAPHITE</small></div><span class="concept-caption">K75 / GRAPHITE EDITION</span></div></section><section class="panel launch-card"><div class="small-label">FEATURED PRODUCT / 01</div><div class="scope-icon">${icon('mail',24)}</div><h3>Vela K75 · Find Your Rhythm</h3><p>75% layout. Hot-swappable switches. USB-C wired. Three colour concepts for a more considered desk.</p><div class="product-swatches"><span><i class="swatch graphite"></i>Graphite</span><span><i class="swatch cloud"></i>Cloud</span><span><i class="swatch moss"></i>Moss</span></div><a class="text-link" href="#campaign/c-autumn/brief">View the launch brief ${icon('chevron',15)}</a><div class="scope-footer"><span class="badge muted">K75 collection · US$129</span><span>NEW COLLECTION</span></div></section></div><div class="metric-grid"><div class="metric-card"><div class="metric-label">Campaigns ${icon('layers',17)}</div><strong>${state.campaigns.length}</strong><span>${active} in progress <small>· saved in workspace</small></span></div><div class="metric-card"><div class="metric-label">Awaiting human review ${icon('shield',17)}</div><strong>${reviews.toString().padStart(2,'0')}</strong><span>Version-specific approval</span></div><div class="metric-card"><div class="metric-label">Audience pool ${icon('users',17)}</div><strong>2,780</strong><span>Across saved segments</span></div><div class="metric-card"><div class="metric-label">Acknowledged records ${icon('mail',17)}</div><strong>${number(sent)}</strong><span>Across completed campaign runs</span></div></div><div class="campaign-grid"><section class="panel campaign-table-panel"><div class="panel-header"><div><h2>All Campaigns <span class="count">${state.campaigns.length}</span></h2><p>One clear record for every campaign.</p></div><label class="search-label">${icon('grid',16)}<input id="campaign-search" type="search" placeholder="Search campaigns" aria-label="Search campaigns" value="${escape(ui.search)}"></label></div><div class="filter-tabs" role="group" aria-label="Campaign filters">${[['all','All campaigns'],['attention','Needs attention'],['draft','Drafts'],['completed','Completed']].map(([id,label])=>`<button class="${ui.filter===id?'selected':''}" data-action="filter" data-value="${id}" aria-pressed="${ui.filter===id}">${label}</button>`).join('')}</div><div class="table-scroll"><table><thead><tr><th>CAMPAIGN</th><th>STATUS</th><th>AUDIENCE</th><th>START · UTC</th><th><span class="sr-only">Open</span></th></tr></thead><tbody>${list.map(c=>`<tr><td><a href="#campaign/${c.id}/brief" class="campaign-name"><span class="campaign-icon ${c.brief.productIds[0]==='p2'?'ochre':''}">${icon('mail',18)}</span><span><strong>${escape(c.brief.name)}</strong><small>EDM · ${c.brief.discount}% offer · ${count(c.brief.productIds.length,'product')}</small></span></a></td><td>${badge(c)}</td><td>${number(audiences[c.brief.audience].eligible)}<small>${audiences[c.brief.audience].name}</small></td><td>${shortDate(c.brief.start)}</td><td><a class="icon-btn" href="#campaign/${c.id}/brief" aria-label="Open ${escape(c.brief.name)}">${icon('chevron',18)}</a></td></tr>`).join('')||'<tr><td colspan="5" class="empty">No campaigns match. Choose another filter or clear the search.</td></tr>'}</tbody></table></div></section><aside class="panel audience-panel"><div class="panel-header"><div><h2>Audience Readiness</h2><p>Engaged subscriber segment</p></div>${icon('users',18)}</div><div class="readiness-number"><strong>860</strong><span>eligible / 1,240</span></div><div class="audience-bar" role="img" aria-label="860 eligible, 180 opted out, 60 duplicates, 140 frequency capped"><span style="width:69.35%"></span><span style="width:14.52%"></span><span style="width:4.84%"></span><span style="width:11.29%"></span></div><div class="audience-legend">${[['Eligible audience',860,'green'],['No active consent',180,'ochre'],['Duplicate records',60,'gray'],['Frequency capped',140,'blue']].map(([label,n,color])=>`<div><span><i class="legend-dot ${color}"></i>${label}</span><strong>${number(n)}</strong></div>`).join('')}</div><div class="insight-note">${icon('shield',17)}<p>Eligibility is checked before content approval.<br><span>Consent and frequency limits inform the review.</span></p></div></aside></div><div class="panel boundary-strip"><span class="boundary-icon">${icon('info',20)}</span><div><strong>A consistent story across every touchpoint</strong><p>From the K75 product brief to the EDM, editorial story and listing: the same facts, offer and visual direction.</p></div><a href="#capabilities" class="text-link">View supporting content ${icon('chevron',15)}</a></div>`;
}
function stageIndex(c){return ['draft'].includes(c.status)?0:['preparing','prep_paused','prep_error'].includes(c.status)?1:['review','approved'].includes(c.status)?2:3;}
function campaign(c){if(!c)return `${pageHead('CAMPAIGN','Campaign unavailable','The demo may have been reset.')}<a class="btn primary" href="#overview">Return to campaigns</a>`;
  const tab=route.tab;const i=stageIndex(c);
  return `<a class="back-link" href="#overview">${icon('back',15)}All campaigns</a>${pageHead('EDM CAMPAIGN',escape(c.brief.name),`<span class="campaign-meta">${badge(c)} <span>${c.brief.goal} · ${c.id} · Vela Studio</span></span>`,button('Duplicate','duplicate','secondary',`data-id="${c.id}"`,'layers'))}<nav class="stepper" aria-label="Campaign Workflow">${[['brief','Campaign Brief','Products, goal and offer'],['prepare','Automatic Preparation','Checks and preparation decisions'],['review','Human Review','Content versions and approval'],['execute','Execution Tracking','Simulated execution and recovery']].map(([id,label,description],j)=>`<a href="#campaign/${c.id}/${id}" class="step ${tab===id?'active':''} ${j<i?'done':''}"><span class="step-number">${j<i?icon('check',16):j+1}</span><span><strong>${label}</strong><small>${description}</small></span></a>`).join('')}</nav>${tab==='prepare'?prepareView(c):tab==='review'?reviewView(c):tab==='execute'?executeView(c):briefView(c)}`;
}
function briefView(c){const a=audiences[c.brief.audience];return `<div class="detail-grid"><section class="panel brief-panel"><div class="panel-header"><div><h2>Campaign Brief</h2><p>Launch the Vela K75: one approved brief across every output.</p></div>${button('Edit brief','editBrief','secondary',lockedStatuses.includes(c.status)?'disabled title="Duplicate the campaign to edit a new execution"':'','file')}</div><div class="brief-summary"><div><small>CAMPAIGN GOAL</small><strong>${c.brief.goal}</strong></div><div><small>CHANNEL</small><strong>${icon('mail',17)} EDM · Independent store</strong></div><div><small>OFFER</small><strong>${c.brief.discount}% off <code>${escape(c.brief.code)}</code></strong></div><div><small>CAMPAIGN WINDOW · UTC</small><strong>${shortDate(c.brief.start)} — ${shortDate(c.brief.end)}</strong></div></div><div class="launch-story"><span class="small-label">PRODUCT LAUNCH CONTEXT</span><h3>A keyboard for your everyday rhythm.</h3><p>A new independent-store launch for desk enthusiasts. Introduce the K75, show its colour options and support the same offer across EDM, Blog and listing previews.</p><div class="spec-chips"><span>75% compact layout</span><span>Hot-swappable switches</span><span>USB-C wired</span></div><small>K75 / 75% mechanical keyboard collection</small></div><h3 class="section-label">Featured Products <span>${c.brief.productIds.length} selected</span></h3><div class="product-list">${c.brief.productIds.map(id=>{const p=products.find(p=>p.id===id);return `<div class="product-item"><div class="product-tile ${p.color}"><img src="${p.image}" alt="${p.name} original concept illustration"></div><div class="product-copy"><strong>${p.name}</strong><small>${p.sku} · ${p.category}</small><span>${p.facts.join(' · ')}</span></div><div class="product-price"><strong>${currency(p.price)}</strong><small class="${p.stock?'':'error-text'}">${p.stock?`${p.stock} in stock`:'Out of stock'}</small></div></div>`;}).join('')}</div><div class="notice subtle">${icon('info',17)}<span>Product prices, selected colours and stock are checked before preparation.</span></div><div class="panel-action-row"><span>Editing the brief resets preparation and cancels previous approval.</span>${['draft','prep_error','prep_paused'].includes(c.status)?button(c.status==='prep_paused'?'Resume preparation':'Prepare campaign','startPrep','primary','','spark'):`<a class="btn primary" href="#campaign/${c.id}/${iTab(c)}">${c.status==='review'?'Review content':'Continue workflow'}</a>`}</div></section><aside><section class="panel segment-card"><div class="panel-header"><div><h2>Target Audience</h2><p>Consent-aware aggregate selection</p></div>${icon('users')}</div><span class="badge muted">${a.name}</span><div class="segment-total"><strong>${number(a.eligible)}</strong><span>eligible records</span></div><p>${a.note}</p><dl class="breakdown"><div><dt>Starting pool</dt><dd>${number(a.base)}</dd></div><div><dt>No active consent</dt><dd>−${a.unsubscribed}</dd></div><div><dt>Duplicate records</dt><dd>−${a.duplicates}</dd></div><div><dt>Frequency cap</dt><dd>−${a.frequency}</dd></div><div class="total"><dt>Eligible audience</dt><dd>${number(a.eligible)}</dd></div></dl></section><section class="context-card"><span class="small-label">CONTENT CONTEXT</span><h3>One brief. Consistent outputs.</h3><p>The selected offer and catalogue facts inform the EDM. Blog and listing previews reuse the same campaign context.</p>${button('Preview supporting content','extensions','quiet','','layers')}</section></aside></div>`;}
function iTab(c){return ['brief','prepare','review','execute'][stageIndex(c)];}
function prepareView(c){const running=c.status==='preparing',ready=c.prep.step===4;return `<div class="detail-grid"><section class="panel preparation-panel"><div class="panel-header"><div><h2>Automatic Preparation</h2><p>Visible inputs, source checks and preparation decisions.</p></div><span class="badge ${ready?'positive':'muted'}">${c.prep.step} / 4 complete</span></div><div class="progress-track"><span style="width:${c.prep.step*25}%"></span></div><div class="preparation-steps">${preparationSteps.map((s,i)=>`<div class="prep-step ${i<c.prep.step?'complete':i===c.prep.step&&running?'working':''}"><div class="prep-icon">${i<c.prep.step?icon('check',19):i===c.prep.step&&running?'<span class="spinner"></span>':i+1}</div><div><h3>${s.title}</h3><p>${s.note}</p>${i<c.prep.step?`<div class="step-result">${i===0?`Catalogue fields present · ${count(c.brief.productIds.length,'product')} in stock · ${c.brief.discount}% offer within range`:i===1?`${number(audiences[c.brief.audience].base)} input → ${number(audiences[c.brief.audience].eligible)} eligible · exclusions explained in the brief`:i===2?`Vela K75 launch template · content v${c.revision} · keyboard artwork + Blog + listing context`:'Price, discount, code and product facts matched · human review still required'}</div>`:''}${c.status==='prep_error'&&i===c.prep.step?`<div class="notice danger">${escape(c.prep.error)}</div>`:''}</div><span class="prep-state">${i<c.prep.step?'Passed':i===c.prep.step&&running?'Running':'Pending'}</span></div>`).join('')}</div>${c.status==='prep_paused'?'<div class="notice warning">Preparation paused. Refreshes preserve completed steps; resume explicitly.</div>':''}<div class="panel-action-row"><span>${ready?'Preparation is complete. Human approval is still required.':'Pause at any time and resume from the last completed step.'}</span>${running?button('Pause preparation','pausePrep','secondary','','pause'):ready?`<a class="btn primary" href="#campaign/${c.id}/review">Review content</a>`:c.status==='prep_error'?button('Correct brief','editBrief','primary','','file'):button(c.status==='prep_paused'?'Resume preparation':'Start preparation','startPrep','primary','','spark')}</div></section><aside><section class="panel explain-panel"><div class="prep-product-preview"><img src="${products.find(p=>p.id===c.brief.productIds[0]).image}" alt="Vela K75 selected product artwork"><div><span class="small-label">SELECTED PRODUCT / K75</span><strong>${products.find(p=>p.id===c.brief.productIds[0]).name}</strong></div></div><h2>Why These Steps?</h2><p>Every prepared output has an understandable source.</p><div class="explain-row"><strong>Input</strong><span>Campaign brief + product catalogue + aggregate audience rules</span></div><div class="explain-row"><strong>Decision</strong><span>Available stock, active consent, offer consistency and frequency cap</span></div><div class="explain-row"><strong>Output</strong><span>A K75 launch email and artwork, ready for human review</span></div><div class="notice subtle">${icon('shield',18)}<span>Human approval is required before scheduling.</span></div></section><section class="context-card"><h3>Connected Product Context</h3><p>Preparation keeps product facts, campaign offer and visual direction together. Human review remains the final gate.</p><a href="#capabilities" class="text-link">Read the capability map</a></section></aside></div>`;}
function artwork(c,compact=false){const selected=products.find(p=>p.id===c.brief.productIds[0]);const image=selected.image;return `<div class="campaign-art keyboard-art ${c.content?.artwork==='horizon'?'horizon':''} ${compact?'compact':''}"><div class="art-top"><span>VELA STUDIO</span><small>NEW / K75 COLLECTION</small></div><div class="art-copy"><small>75% MECHANICAL KEYBOARD</small><strong>Find your<br>own rhythm.</strong><span>COMPACT. CONSIDERED. YOURS.</span></div><img class="art-keyboard" src="${image}" alt="Vela K75 keyboard concept illustration"><div class="art-offer">${c.brief.discount}%<small>LAUNCH OFFER</small></div><div class="art-caption">VELA K75 / LAUNCH COLLECTION</div></div>`;}
function emailPreview(c){return `<div class="email-shell"><div class="email-envelope"><div><span>FROM</span> Vela Studio &lt;hello@vela.example&gt;</div><div><span>SUBJECT</span> ${escape(c.content.subject)}</div><div><span>PREHEADER</span> ${escape(c.content.preheader)}</div></div><div class="email-brand">VELA <span>STUDIO</span></div>${artwork(c)}<div class="email-body"><span class="small-label">THE K75 LAUNCH COLLECTION</span><h2>${escape(c.content.headline)}</h2><p>${escape(c.content.body)}</p><div class="email-products">${c.brief.productIds.map(id=>{const p=products.find(p=>p.id===id);return `<div><img class="email-product-img" src="${p.image}" alt="${p.name}"><span>${p.category}</span><strong>${p.name}</strong><small>${currency(p.price)} · ${p.facts[0]}</small></div>`;}).join('')}</div><span class="email-cta">${escape(c.content.cta)} ${icon('external',14)}</span><small class="email-cta-note"></small><div class="offer-line">${escape(c.brief.code)} · ${c.brief.discount}% off · valid until ${shortDate(c.brief.end)} UTC</div></div><div class="email-footer">Vela Studio · Desk essentials<br>You’re receiving this email because you subscribed to Vela Studio.<br><span>Preferences · Unsubscribe </span></div></div>`;}
function reviewView(c){if(!c.content)return `<section class="panel empty-state">${icon('file',38)}<h2>No Draft to Review Yet</h2><p>Complete automatic preparation to create a sample EDM.</p><a class="btn primary" href="#campaign/${c.id}/prepare">Open preparation</a></section>`;
  const locked=lockedStatuses.includes(c.status),checks=ui.checks[c.id]||{};
  return `<div class="review-layout"><section class="panel email-preview-panel"><div class="panel-header"><div><h2>EDM Preview <span class="badge muted">v${c.revision}</span></h2><p>Vela K75 launch · email and product artwork preview</p></div>${button('Edit content','editContent','secondary',locked?'disabled':'','file')}</div>${emailPreview(c)}</section><aside class="review-controls"><section class="panel approval-card"><div class="panel-header"><div><h2>Human Approval</h2><p>Approval is bound to this version.</p></div>${icon('shield',20)}</div>${c.approvedRevision===c.revision?`<div class="approval-status">${icon('check',20)}<div><strong>Version ${c.revision} approved</strong><span>Any edit cancels this approval.</span></div></div>`:c.returned?'<div class="notice warning">Returned for revision. Edit and save content before it can be approved again.</div>':'<div class="notice subtle">Review all facts and the audience rules before approving this version.</div>'}<div class="fact-list"><div><span>Offer</span><strong>${c.brief.discount}% · ${escape(c.brief.code)}</strong>${icon('check',16)}</div><div><span>Product facts</span><strong>${count(c.brief.productIds.length,'catalogue match','catalogue matches')}</strong>${icon('check',16)}</div><div><span>Audience</span><strong>${number(audiences[c.brief.audience].eligible)} consent-eligible</strong>${icon('check',16)}</div><div><span>Unsupported claims</span><strong>Manual verification required*</strong>${icon('info',16)}</div></div><small class="fact-disclaimer">*Review every edited claim against the catalogue. Automated checks support the reviewer’s decision.</small>${c.status==='review'?`<label class="check-row"><input type="checkbox" id="facts-check" ${checks.facts?'checked':''} ${c.returned?'disabled':''}><span>I checked product facts, pricing and the offer window.</span></label><label class="check-row"><input type="checkbox" id="consent-check" ${checks.consent?'checked':''} ${c.returned?'disabled':''}><span>I reviewed audience eligibility and frequency limits.</span></label>${button(`Approve version ${c.revision}`,'approve','primary full',(!checks.facts||!checks.consent||c.returned)?'disabled':'','check')}`:''}${['review','approved','scheduled'].includes(c.status)?button('Return for revision','return','secondary full','','back'):''}<p class="small-note">Approval applies to this content version. Editing requires a new review.</p>${['approved','scheduled'].includes(c.status)?`<a class="btn primary full" href="#campaign/${c.id}/execute">Continue to execution</a>`:''}</section><section class="panel sources-card"><h3>Evidence Behind the Draft</h3><p>Catalogue details behind the approved campaign.</p>${c.brief.productIds.map(id=>{const p=products.find(p=>p.id===id);return `<div><span class="source-icon">${icon('file',17)}</span><div><strong>${p.name}</strong><small>${p.sku} · ${currency(p.price)}</small><p>${p.facts.join(' · ')}</p></div></div>`;}).join('')}<a class="text-link" href="#campaign/${c.id}/brief">Inspect campaign inputs</a></section></aside></div>`;}
function executeView(c){const d=c.delivery;
  return `<section class="panel execution-banner"><img class="execution-product" src="${products.find(p=>p.id===c.brief.productIds[0]).image}" alt="Vela K75 campaign product concept"><div class="execution-banner-icon">${icon(d?'chart':'clock',25)}</div><div><h2>${d?'Campaign Run':'Delivery Execution'}</h2><p>${d?`${d.runId} · version ${c.approvedRevision} · ${number(d.total)} aggregate records`:`Version ${c.revision||'—'} · ${number(audiences[c.brief.audience].eligible)} eligible records`}</p></div><span class="badge muted">${d?'VERSION LOCKED':approveReady(c)?'APPROVED VERSION':'REVIEW REQUIRED'}</span></section>${!d?`<div class="detail-grid"><section class="panel send-panel"><h2>Review the Delivery Plan</h2><p>Starting a run freezes the approved content and eligible audience. Start explicitly when the campaign is ready.</p><div class="send-gates"><div>${icon(approveReady(c)?'check':'close',18)}<span>Current content version approved</span><strong>${approveReady(c)?`v${c.revision} approved`:'Required'}</strong></div><div>${icon('check',18)}<span>Audience eligibility explained</span><strong>${number(audiences[c.brief.audience].eligible)} records</strong></div><div>${icon('check',18)}<span>Batch pacing</span><strong>Controlled batch processing</strong></div></div>${c.status==='scheduled'?`<div class="notice positive">${icon('clock',18)}<span>Reservation: ${shortDate(c.brief.start)} UTC. Start the run when ready.</span></div>`:!approveReady(c)?`<div class="notice warning">Prepare and approve the current content version before starting.</div>`:''}<div class="send-actions">${c.status==='scheduled'?button('Cancel reservation','cancelSchedule','secondary'):button('Reserve campaign','schedule','secondary',c.status!=='approved'?'disabled':'','clock')}${button('Start campaign run','startSend','primary',!approveReady(c)?'disabled':'','play')}</div><p class="small-note">The current content version must be approved before a run can start.</p></section><aside class="panel scenario-panel"><span class="small-label">RECOVERY SCENARIO</span><h2>Make recovery visible.</h2><p>Two distinct outcomes need different recovery actions.</p><div class="scenario"><span class="scenario-number">01</span><div><strong>429 · Rate-limited batch</strong><p>Known failures enter a short backoff, then retry with the same batch key.</p></div></div><div class="scenario"><span class="scenario-number">02</span><div><strong>Timeout · Outcome uncertain</strong><p>Reconcile receipts before doing anything else. Never retry an unknown outcome.</p></div></div></aside></div>`:`<div class="delivery-metrics">${[['Acknowledged',d.sent,'green'],['Retryable failure',d.failed,'red'],['Needs reconciliation',d.unknown,'ochre'],['Queued',d.queued,'gray']].map(([label,n,color])=>`<div class="delivery-metric ${color}"><span>${label}</span><strong>${number(n)}</strong><small>Records</small></div>`).join('')}</div><div class="detail-grid"><section class="panel tracking-panel"><div class="panel-header"><div><h2>Execution Status</h2><p>A stable run ID and batch keys prevent duplicate work.</p></div>${badge(c)}</div><div class="delivery-progress" role="img" aria-label="${d.sent} acknowledged, ${d.failed} failed, ${d.unknown} uncertain, ${d.queued} queued"><span class="green" style="width:${d.sent/d.total*100}%"></span><span class="red" style="width:${d.failed/d.total*100}%"></span><span class="ochre" style="width:${d.unknown/d.total*100}%"></span><span class="gray" style="width:${d.queued/d.total*100}%"></span></div><div class="tracking-meta"><span>${Math.round(d.sent/d.total*100)}% acknowledged</span><strong>${number(d.sent)} / ${number(d.total)}</strong></div>${c.status==='running'?`<div class="notice subtle"><span class="spinner"></span><span>Processing batches. Navigation is safe; refreshing pauses the run.</span></div>${button('Pause run','pauseSend','secondary','','pause')}`:''}${c.status==='delivery_paused'?`<div class="notice warning">Run paused. Acknowledged records and batch cursor are preserved.</div>${button('Resume run','resumeSend','primary','','play')}`:''}${c.status==='retry_wait'?`<div class="notice warning"><span class="spinner"></span><span>Rate-limit backoff · <strong id="retry-countdown">${Math.max(0,Math.ceil((d.retryAt-Date.now())/1000))}</strong>s remaining. Only the failed batch will retry.</span></div>${button('Retry in progress','retry','secondary','disabled')}`:''}${c.status==='needs_attention'||c.status==='retry_wait'?`<div class="recovery-cards"><div class="recovery-card"><span class="badge danger">429 · RETRYABLE</span><h3>${number(d.failed)} known failures</h3><p>3-second backoff. Same run and batch key. Repeated clicks create one attempt.</p>${button(d.failed?'Retry failed batch':'Failed batch recovered','retry',d.failed?'primary':'secondary',(!d.failed||c.status==='retry_wait')?'disabled':'','reset')}</div><div class="recovery-card"><span class="badge warning">TIMEOUT · UNCERTAIN</span><h3>${number(d.unknown)} uncertain outcomes</h3><p>Query receipt records to determine whether the batch was already accepted. No resend.</p>${button(d.unknown?'Reconcile receipts':'Receipts reconciled','reconcile','secondary',(!d.unknown||c.status==='retry_wait')?'disabled':'','shield')}</div></div>`:''}${c.status==='completed'?`<div class="completion-card">${icon('check',27)}<div><h3>Campaign Run complete</h3><p>${number(d.sent)} receipts. ${d.reconciled?'Unknown outcomes reconciled without resending.':'All batch outcomes are recorded.'}</p></div></div><div class="completion-actions"><a href="#overview" class="btn secondary">Back to campaigns</a>${button('Duplicate for another run','duplicate','primary',`data-id="${c.id}"`,'layers')}</div>`:''}</section><aside class="panel rules-panel"><h2>Delivery Guardrails</h2><div class="rule">${icon('shield',19)}<div><strong>Frozen approved version</strong><p>Execution locks campaign inputs. Start a new campaign for new content.</p></div></div><div class="rule">${icon('reset',19)}<div><strong>Safe retries</strong><p>Retry known failures only. Keep the original idempotency key.</p></div></div><div class="rule">${icon('clock',19)}<div><strong>Rate-limit backoff</strong><p>The mock clock enforces a short wait before the retry.</p></div></div><div class="rule">${icon('file',19)}<div><strong>Auditable decisions</strong><p>Each transition is recorded with a time and explanation.</p></div></div><div class="notice subtle">Track decisions and outcomes with the same campaign and batch identifiers.</div></aside></div>`}${auditPanel(c)}`;
}
function auditPanel(c){return `<section class="panel audit-panel"><div class="panel-header"><div><h2>Audit Trail</h2><p>Latest event first · UTC · campaign history</p></div><span class="badge muted">${count(c.audit.length,"event")}</span></div><div class="audit-list">${c.audit.map(e=>`<div class="audit-event"><span class="audit-marker"></span><time>${shortDate(e.at)}</time><div><strong>${escape(e.type)}</strong><p>${escape(e.detail)}</p></div><code>${escape(e.id)}</code></div>`).join('')}</div></section>`;}
function reviewQueue(){const cs=state.campaigns.filter(c=>c.status==='review');return `${pageHead('HUMAN IN THE LOOP','Review Queue','Check the message, its sources and the audience before anything moves forward.')}<div class="notice subtle">${icon('shield',19)}<span>Every approval applies to a specific content version. Editing cancels previous approval. </span></div>${cs.length?`<div class="queue-grid">${cs.map(c=>`<article class="panel queue-card">${artwork(c,true)}<div class="queue-content">${badge(c)}<h2>${escape(c.brief.name)}</h2><p>${escape(c.content.subject)}</p><div class="queue-meta"><span>v${c.revision} · ${count(c.brief.productIds.length,'product')}</span><span>${number(audiences[c.brief.audience].eligible)} eligible</span></div><a href="#campaign/${c.id}/review" class="btn primary full">Open review</a></div></article>`).join('')}</div>`:'<section class="panel empty-state">'+icon('check',38)+'<h2>You Are All Caught Up</h2><p>Prepared campaigns will appear here for human approval.</p><a class="btn secondary" href="#overview">Back to campaigns</a></section>'}`;}
function executions(){const cs=state.campaigns.filter(c=>c.delivery||c.status==='scheduled');return `${pageHead('OBSERVE & RECOVER','Execution Log','Follow batch outcomes and the decisions that resolve them.')}<div class="notice warning">${icon('info',18)}<span>Outcome uncertain? Reconcile receipts before retrying.</span></div><section class="panel execution-table"><div class="panel-header"><h2>Campaign Executions</h2><span class="badge muted">${count(cs.length,"campaign run")}</span></div><div class="table-scroll"><table><thead><tr><th>CAMPAIGN / RUN</th><th>STATUS</th><th>ACKNOWLEDGED</th><th>FAILED</th><th>UNCERTAIN</th><th></th></tr></thead><tbody>${cs.map(c=>`<tr><td><a href="#campaign/${c.id}/execute"><strong>${escape(c.brief.name)}</strong><small>${c.delivery?.runId||'Reservation only'}</small></a></td><td>${badge(c)}</td><td>${number(c.delivery?.sent)}</td><td><span class="${c.delivery?.failed?'error-text':''}">${number(c.delivery?.failed)}</span></td><td>${number(c.delivery?.unknown)}</td><td><a class="icon-btn" href="#campaign/${c.id}/execute" aria-label="Inspect ${escape(c.brief.name)} execution">${icon('chevron',18)}</a></td></tr>`).join('')||'<tr><td colspan="6" class="empty">No runs yet. Approve a prepared campaign to begin.</td></tr>'}</tbody></table></div></section><section class="panel boundary-strip"><span class="boundary-icon">${icon('shield')}</span><div><strong>Outcome uncertain? Reconcile first.</strong><p>A timeout can hide a successful delivery. This demo keeps those records separate from known failures.</p></div><a href="#overview" class="text-link">Open campaigns</a></section>`;}
function capabilities(){return `${pageHead('CAPABILITY BOUNDARIES','From EDM to Connected Marketing','A focused first release, with a clear path to a broader marketing workspace.')}<div class="capability-intro"><div><span class="pill">CURRENT FOCUS · INDEPENDENT STORES</span><h2>EDM operations,<br>with people in control.</h2><p>The first release connects campaign planning, automatic preparation, human review and execution tracking. Cross-platform marketing is the long-term direction.</p></div><div class="roadmap-mini"><span class="current">01 <strong>Independent store / EDM</strong></span><span>02 <strong>Blog + listing support</strong></span><span>03 <strong>Amazon + TikTok</strong></span></div></div><div class="capability-grid"><section class="panel capability-card"><span class="badge muted">EXISTING EDM PRACTICE</span>${icon('mail',27)}<h2>Existing EDM Practice</h2><p>The team has Blog + EDM generation code and documented EDM workflow evidence.</p><ul><li>Source EDM MVP: independent-store selection, preparation, submission and reconciliation.</li><li>Source v0.2: approval, immutable versions and task recovery have local validation evidence.</li><li>Those source capabilities are separate from this frontend; their production gates remain distinct.</li></ul><div class="capability-note">Based on team code and the latest local EDM documentation. See repository notes for evidence and validation boundaries.</div></section><section class="panel capability-card emphasis"><span class="badge positive">LOCAL DEMONSTRATION</span>${icon('shield',27)}<h2>Interactive Workflow</h2><p>This local prototype makes the operational flow concrete and reviewable.</p><ul><li>Brief validation and explainable preparation</li><li>Version approval and cancellation after edits</li><li>Simulated reservations, retries and receipt reconciliation</li><li>Browser refresh recovery and campaign isolation</li></ul><div class="capability-note">Fictional aggregate data, fixed templates and simulated states. No model or platform calls.</div></section><section class="panel capability-card"><span class="badge warning">FUTURE PLAN</span>${icon('layers',27)}<h2>Connected Execution</h2><p>Production integrations require a separate implementation and validation.</p><ul><li>Store catalogue, consent and email providers</li><li>Model generation with factual grounding</li><li>Server-side queues, limits and idempotency</li><li>Amazon and TikTok workflows after the EDM release</li></ul><div class="capability-note">Live integrations, model generation and production execution are planned, not implemented here.</div></section></div><div class="section-heading"><div><h2>Supporting Content, Same Campaign Context</h2><p>Secondary entry points with a specific role in the EDM workflow.</p></div></div><div class="extension-grid"><section class="panel extension-card"><span class="extension-icon">${icon('file',23)}</span><div><span class="small-label">BLOG · SUPPORTING ENTRY</span><h3>Show the Keyboard Behind the Email</h3><p>Preview an editorial brief linked to the campaign offer and products. The blog can become the email's destination.</p>${button('Preview editorial brief','blog','secondary')}</div></section><section class="panel extension-card"><span class="extension-icon blue">${icon('layers',23)}</span><div><span class="small-label">PRODUCT LISTING · SUPPORTING ENTRY</span><h3>Preview the K75 Product Destination</h3><p>Preview catalogue fields and an offer checklist before a future store listing workflow. Publishing is a future integration.</p>${button('Preview listing checklist','listing','secondary')}</div></section></div><section class="panel future-platforms"><div><h2>Future Platform Roadmap</h2><p>Not connected. No external accounts or data used.</p></div><div><span>Amazon <small>Catalogue + marketplace content</small></span><span>TikTok <small>Campaign assets + channel adaptation</small></span></div></section>`;}
function guidePanel(){const g=state.guide;if(!g)return '';const c=state.campaigns.find(c=>c.id===g.id);if(!c)return '';
  let step=0,title='Confirm the campaign brief',desc='Review the products, offer and eligible audience, then begin preparation.',action=button('Prepare campaign','guidePrepare','primary full');
  if(['preparing','prep_paused','prep_error'].includes(c.status)){step=1;title='Watch preparation explain its work';desc='Follow the product checks, audience rules and email artwork preparation. Pause and resume as needed.';action=c.status==='preparing'?button('Preparing sample…','noop','secondary full','disabled'):button('Resume preparation','guidePrepare','primary full');}
  if(c.status==='review'){step=2;title=c.returned?'Revise the returned content':'Review and approve the draft';desc='Review the email and artwork, confirm the facts and audience checks, then approve this version. Editing cancels approval.';action=`<a class="btn primary full" href="#campaign/${c.id}/review">Open human review</a>`;}
  if(c.status==='approved'){step=3;title='Reserve the approved campaign';desc='Reserve the approved campaign, then explicitly start its simulated run.';action=button('Reserve campaign','guideSchedule','primary full');}
  if(c.status==='scheduled'){step=3;title='Start the campaign run';desc='This version is approved. Start the run to follow acknowledged, failed and uncertain batches.';action=button('Start campaign run','guideSend','primary full');}
  if(['running','delivery_paused'].includes(c.status)){step=4;title='Track the campaign batches';desc='When rate limits and timeouts occur, handle known failures and uncertain outcomes separately.';action=c.status==='running'?button('Campaign running…','noop','secondary full','disabled'):button('Resume run','guideResume','primary full');}
  if(['needs_attention','retry_wait'].includes(c.status)){step=4;title=c.delivery.failed?'Recover the failed batch':'Reconcile uncertain receipts';desc=c.delivery.failed?'Retry only known failures after the backoff. Do not resend records with uncertain outcomes.':'Look up receipts to confirm whether uncertain records were already accepted, without resending.';action=c.status==='retry_wait'?button('Backoff in progress…','noop','secondary full','disabled'):button(c.delivery.failed?'Retry failed batch':'Reconcile receipts',c.delivery.failed?'guideRetry':'guideReconcile','primary full');}
  if(c.status==='completed'){step=5;title='The workflow is complete';desc='The campaign has moved from brief to approval and recovery. Review its decisions and simulated outcomes in the audit trail.';action=button('Finish walkthrough','guideFinish','primary full');}
  return `<aside class="guide-panel" aria-label="Guided demo"><div class="guide-top"><span>${icon('play',14)} LAUNCH WALKTHROUGH</span><button class="icon-btn" data-action="guideClose" aria-label="Close walkthrough">${icon('close',17)}</button></div><div class="guide-dots">${[0,1,2,3,4,5].map(i=>`<span class="${i<=step?'filled':''}"></span>`).join('')}</div><div class="guide-step">STEP ${step+1} OF 6</div><h3>${title}</h3><p>${desc}</p>${action}<a class="guide-link" href="#campaign/${c.id}/${iTab(c)}">Open walkthrough campaign</a></aside>`;
}
function render(){if(legacyRaw){$('#app').innerHTML=shell(languageGate());document.title='Saved Workspace Review · Relay';return;}let content=route.view==='campaign'?campaign(current()):route.view==='review'?reviewQueue():route.view==='execution'?executions():route.view==='capabilities'?capabilities():overview();$('#app').innerHTML=shell(content);document.title=`${route.view==='campaign'&&current()?current().brief.name:({overview:'Campaigns',review:'Review Queue',execution:'Execution Log',capabilities:'Capabilities'})[route.view]||'Workspace'} · Relay`;}
function run(action,payload={},c=current()){if(!c)return;const result=transition(c,action,payload);if(result.ok){persist();render();}toast(result.message);return result;}
function openModal(title,body,footer='',kind='info'){
  ui.lastFocus=document.activeElement;ui.modal=kind;
  $('#dialog-root').innerHTML=`<dialog class="modal ${kind==='content'?'wide':''}" aria-labelledby="modal-title"><div class="modal-header"><div><span class="small-label">VELA STUDIO / WORKSPACE</span><h2 id="modal-title">${title}</h2></div><button class="icon-btn" type="button" data-action="closeModal" aria-label="Close dialog">${icon('close')}</button></div>${body}${footer?`<div class="modal-footer">${footer}</div>`:''}</dialog>`;
  const dialog=$('dialog');dialog.addEventListener('cancel',e=>{e.preventDefault();closeModal();});dialog.showModal();
}
function closeModal(){if(ui.modal==='brief'||ui.modal==='content')toast('Dialog closed. Unsaved changes were discarded.');$('dialog')?.close();$('#dialog-root').innerHTML='';ui.modal=null;if(ui.lastFocus?.isConnected)ui.lastFocus.focus();}
function briefModal(c=null){const b=c?.brief||{...defaultBrief(),name:''};const action=c?'Save brief':'Create campaign';
  openModal(c?'Edit Campaign Brief':'New EDM Campaign',`<form id="brief-form" novalidate data-id="${c?.id||''}"><div class="modal-body"><p class="modal-intro">Choose the products, audience, offer and campaign window.<br><span>Complete the required fields. Cancelling leaves the campaign unchanged.</span></p><div id="form-errors" class="form-errors" role="alert"></div><label class="field">Campaign name <span>*</span><input name="name" maxlength="80" value="${escape(b.name)}" placeholder="e.g. K75 launch · Early access" required><small id="error-name"></small></label><fieldset class="product-select"><legend>Featured products <span>*</span></legend>${products.map(p=>`<label><input type="checkbox" name="productIds" value="${p.id}" ${b.productIds.includes(p.id)?'checked':''}><img class="select-product-image" src="${p.image}" alt="${p.name} concept"><span><strong>${p.name}</strong><small>${p.sku} · ${currency(p.price)}</small></span><span class="badge ${p.stock?'muted':'warning'}">${p.stock?'In stock':'Out of stock'}</span></label>`).join('')}<small id="error-products" class="field-error"></small></fieldset><div class="form-columns"><label class="field">Campaign goal <span>*</span><select name="goal">${['Product discovery','Repeat purchase','Re-engagement'].map(x=>`<option ${x===b.goal?'selected':''}>${x}</option>`).join('')}</select></label><label class="field">Target audience <span>*</span><select name="audience">${Object.entries(audiences).map(([id,a])=>`<option value="${id}" ${id===b.audience?'selected':''}>${a.name} · ${number(a.eligible)} eligible</option>`).join('')}</select></label></div><div class="form-columns"><label class="field">Offer discount (%) <span>*</span><input name="discount" type="number" min="1" max="50" value="${b.discount}" required><small id="error-discount"></small></label><label class="field">Offer code <span>*</span><input name="code" maxlength="20" value="${escape(b.code)}" placeholder="K75LAUNCH" required><small id="error-code"></small></label></div><div class="form-columns"><label class="field">Start time (UTC) <span>*</span><input name="start" type="text" value="${b.start.replace('T',' ')}" placeholder="YYYY-MM-DD HH:mm" autocomplete="off" required><small id="error-start"></small></label><label class="field">Offer ends (UTC) <span>*</span><input name="end" type="text" value="${b.end.replace('T',' ')}" placeholder="YYYY-MM-DD HH:mm" autocomplete="off" required><small id="error-end"></small></label></div><p class="small-note">Enter UTC times as YYYY-MM-DD HH:mm, using the 24-hour clock.</p>${c?'<div class="notice warning">Saving the brief resets preparation and cancels prior approval or reservation.</div>':''}</div><div class="modal-footer">${button('Cancel','closeModal','secondary','type="button"')}<button type="submit" class="btn primary">${action}</button></div></form>`,'','brief');
}
function contentModal(c){openModal(`Edit EDM · version ${c.revision}`,`<form id="content-form" novalidate data-id="${c.id}"><div class="modal-body"><div class="notice warning">Saving creates a new version and cancels the old approval and reservation. A new review is required after editing.</div><div id="content-errors" role="alert" class="form-errors"></div>${[['subject','Subject line',150],['preheader','Preheader',180],['headline','Email headline',150],['body','Message body',1800],['cta','CTA label',60]].map(([k,label,max])=>`<label class="field">${label} <span>*</span>${k==='body'?`<textarea name="${k}" rows="5" maxlength="${max}" required>${escape(c.content[k])}</textarea>`:`<input name="${k}" value="${escape(c.content[k])}" maxlength="${max}" required>`}</label>`).join('')}<fieldset class="art-select"><legend>Campaign artwork · product artwork layouts</legend>${[['slate','Studio light'],['horizon','Soft gradient']].map(([id,name])=>`<label><input type="radio" name="artwork" value="${id}" ${c.content.artwork===id?'checked':''}><span class="art-swatch ${id}"></span><span>${name}</span></label>`).join('')}</fieldset><p class="small-note">Choose the visual direction for the K75 launch. Saving requires a new approval.</p></div><div class="modal-footer">${button('Cancel','closeModal','secondary','type="button"')}<button type="submit" class="btn primary">Save new revision</button></div></form>`,'','content');}
function supporting(kind,c=current()||state.campaigns[0]){const p=products.find(p=>p.id===c.brief.productIds[0]);
  const body=kind==='blog'?`<div class="blog-cover"><div><small>VELA JOURNAL / DESK STORIES</small><strong>A little space.<br>A lot of rhythm.</strong></div><img src="${p.image}" alt="Vela K75 keyboard editorial cover"></div><article class="article-sample"><span class="article-meta">DESK CULTURE · 4 MIN READ</span><h3>A Compact Keyboard for a Considered Desk</h3><p>Your desk is where ideas become work. The Vela K75 brings the familiar keys into a 75% layout, leaving more space for the things that help you focus.</p><h4>Choose Your Everyday Colour</h4><p>Graphite feels calm and grounded. Cloud keeps the palette light. Moss introduces a quiet green accent. The K75 concept collection shares the same layout, so colour can be your starting point.</p><h4>Make the Switch Your Own</h4><p>Hot-swappable switches let you explore a different typing feel. A USB-C wired connection keeps the product story straightforward. These are the catalogue facts carried into this launch campaign.</p><h4>The Launch Collection</h4><p>Explore ${c.brief.productIds.map(id=>products.find(p=>p.id===id).name).join(' and ')}. The campaign offers ${c.brief.discount}% off with code <strong>${escape(c.brief.code)}</strong>, valid until ${shortDate(c.brief.end)} UTC.</p><div class="notice subtle">Linked to the same EDM brief, product facts and launch offer. Article publication is a planned integration.</div></article>`:`<div class="listing-card"><div class="listing-art"><img src="${p.image}" alt="${p.name} product listing concept"></div><div class="listing-description"><span class="small-label">VELA STUDIO / K75 COLLECTION</span><h3>${p.name}</h3><div class="listing-price">${currency(p.price)}<small>${c.brief.discount}% launch offer with ${escape(c.brief.code)}</small></div><div class="product-swatches"><span><i class="swatch graphite"></i>Graphite</span><span><i class="swatch cloud"></i>Cloud</span><span><i class="swatch moss"></i>Moss</span></div><p>75% compact layout · Hot-swappable switches · USB-C wired connection</p><div class="listing-mock-cta">Add to cart · page preview</div></div></div><div class="listing-preview"><h4>Listing Readiness Checklist</h4><div class="listing-checkboxes"><span>${icon('check',17)} Product title and selected variant match the EDM</span><span>${icon('check',17)} Price and catalogue attributes share one source</span><span>${icon(p.stock?'check':'close',17)} ${p.stock?p.stock+' units in stock':'Out of stock — block promotion'}</span><span>${icon('check',17)} ${escape(c.brief.code)} · ${c.brief.discount}% · valid until ${shortDate(c.brief.end)} UTC</span></div><p class="small-note">Listing preview and checklist. Store publishing and checkout are planned integrations.</p></div>`;
  openModal(kind==='blog'?'Vela Journal · Article Preview':'Vela K75 · Product Listing Preview',`<div class="modal-body"><div class="small-label">LINKED CAMPAIGN / ${escape(c.brief.name)}</div>${body}</div>`,`${button('Close','closeModal','secondary')}<a class="btn primary" href="#campaign/${c.id}/brief" data-action="closeForLink">Open campaign brief</a>`,kind==='blog'?'content-preview':'listing');
}
document.addEventListener('click',e=>{const el=e.target.closest('[data-action]');if(!el||el.disabled)return;const a=el.dataset.action,c=current();
  if(legacyRaw&&!['downloadLegacy','confirmEnglishDemo','startEnglishDemo','closeModal','about','downloadLanguageBackup'].includes(a)){e.preventDefault();toast('Review your saved workspace before starting the English demo.');return;}
  if(a==='downloadLegacy'){downloadJSON(legacyRaw,'relay-saved-workspace.json');return;}
  if(a==='downloadLanguageBackup'){downloadJSON(localStorage.getItem(BACKUP_KEY),'relay-workspace-backups.json');return;}
  if(a==='confirmEnglishDemo'){openModal('Start the English Demo?',`<div class="modal-body"><p>The original workspace will be kept as a downloadable browser backup. The active workspace will then use three English sample campaigns.</p><p>No saved text, draft or approval will be translated automatically.</p></div>`,button('Cancel','closeModal')+button('Keep backup and start','startEnglishDemo','primary'));return;}
  if(a==='startEnglishDemo'){startEnglishDemo();return;}
  if(a==='menu'){ui.menu=!ui.menu;render();}
  else if(a==='about')aboutModal();
  else if(a==='new')briefModal();
  else if(a==='editBrief')briefModal(c);
  else if(a==='editContent')contentModal(c);
  else if(a==='closeModal'||a==='closeForLink')closeModal();
  else if(a==='filter'){ui.filter=el.dataset.value;render();}
  else if(a==='duplicate'){const old=state.campaigns.find(x=>x.id===el.dataset.id)||c;const id=`c-local-${state.serial++}`;const n=newCampaign(id,{...old.brief,start:defaultBrief().start,end:defaultBrief().end,name:`${old.brief.name.slice(0,68)} · copy`});state.campaigns.unshift(n);persist();go(`campaign/${id}/brief`);toast('Independent draft created. Previous execution remains intact.');}
  else if(a==='reset')openModal('Reset the demo?',`<div class="modal-body"><p>Restore the three original sample campaigns and clear all local walkthroughs, revisions and audit events.</p><p class="small-note">Only this demo workspace is reset. Other files on your computer are unaffected.</p></div>`,`${button('Cancel','closeModal')}${button('Reset demo','confirmReset','danger')}`,'reset');
  else if(a==='confirmReset'){state=seedState();ui.checks={};ui.filter='all';ui.search='';closeModal();persist();go('overview');render();toast('Demo reset. Original fictional sample campaigns restored.');}
  else if(a==='guide'){if(state.guide){const g=state.campaigns.find(c=>c.id===state.guide.id);go(`campaign/${g.id}/${iTab(g)}`);toast('Resumed the existing walkthrough.');}else{const id=`c-guide-${state.serial++}`;state.campaigns.unshift(newCampaign(id,{...defaultBrief(),name:'K75 Launch · Guided Demo'}));state.guide={id};persist();go(`campaign/${id}/brief`);render();}}
  else if(a==='guideClose'){state.guide=null;persist();render();toast('Walkthrough closed. Its campaign is preserved.');}
  else if(a==='guideFinish'){state.guide=null;persist();go('overview');render();toast('Launch walkthrough complete. Review the campaign audit trail.');}
  else if(a.startsWith('guide')){const g=state.campaigns.find(x=>x.id===state.guide?.id);const map={guidePrepare:['startPrep','prepare'],guideSchedule:['schedule','execute'],guideSend:['startSend','execute'],guideResume:['resumeSend','execute'],guideRetry:['retry','execute'],guideReconcile:['reconcile','execute']};if(map[a]){run(map[a][0],{},g);go(`campaign/${g.id}/${map[a][1]}`);}}
  else if(a==='approve'){const checks=ui.checks[c.id]||{};run(a,checks);}
  else if(a==='return'){openModal('Return Content for Revision',`<form id="return-form" novalidate data-id="${c.id}"><div class="modal-body"><label class="field">Revision note <span>*</span><textarea name="note" rows="4" required maxlength="600" placeholder="Explain what needs to change."></textarea></label><div class="form-errors" id="return-errors" role="alert"></div><p class="small-note">This clears the current approval and simulated reservation.</p></div><div class="modal-footer">${button('Cancel','closeModal','secondary','type="button"')}<button class="btn primary" type="submit">Return for revision</button></div></form>`,'','return');}
  else if(a==='extensions')openModal('Supporting Content Previews',`<div class="modal-body"><p>Preview how this brief supports destination content. These are static examples, with no external publishing.</p><div class="extension-modal-actions">${button('Editorial brief','blog','secondary','','file')}${button('Listing checklist','listing','secondary','','layers')}</div></div>`,button('Close','closeModal'));
  else if(a==='blog'||a==='listing'){closeModal();supporting(a);}
  else if(['startPrep','pausePrep','schedule','cancelSchedule','startSend','pauseSend','resumeSend','retry','reconcile'].includes(a)){const r=run(a);if(r?.ok&&a==='startPrep')go(`campaign/${c.id}/prepare`);if(r?.ok&&a==='startSend')go(`campaign/${c.id}/execute`);}
});
document.addEventListener('change',e=>{if(['facts-check','consent-check'].includes(e.target.id)){const c=current();ui.checks[c.id]||={};ui.checks[c.id][e.target.id==='facts-check'?'facts':'consent']=e.target.checked;const b=document.querySelector('[data-action="approve"]');if(b)b.disabled=!ui.checks[c.id].facts||!ui.checks[c.id].consent||c.returned;}});
document.addEventListener('input',e=>{if(e.target.id==='campaign-search'){ui.search=e.target.value;const pos=e.target.selectionStart;render();$('#campaign-search').focus();$('#campaign-search').setSelectionRange(pos,pos);}});
document.addEventListener('submit',e=>{e.preventDefault();const f=e.target,fd=new FormData(f);
  if(f.id==='brief-form'){
    const b={name:String(fd.get('name')||'').trim(),productIds:fd.getAll('productIds'),goal:fd.get('goal'),audience:fd.get('audience'),discount:fd.get('discount')===''?NaN:Number(fd.get('discount')),code:String(fd.get('code')||'').trim(),start:String(fd.get('start')||'').trim().replace(' ','T'),end:String(fd.get('end')||'').trim().replace(' ','T')};const errors=validateBrief(b);
    f.querySelectorAll('.invalid').forEach(x=>{x.classList.remove('invalid');x.removeAttribute('aria-invalid');});f.querySelectorAll('[id^="error-"]').forEach(x=>x.textContent='');
    if(Object.keys(errors).length){$('#form-errors').textContent='Complete the highlighted fields to continue.';Object.entries(errors).forEach(([k,v])=>{const label=$(`#error-${k}`);if(label)label.textContent=v;const input=f.elements[k];if(input?.classList){input.classList.add('invalid');input.setAttribute('aria-invalid','true');}});f.querySelector('.invalid')?.focus();return;}
    if(f.dataset.id){const c=state.campaigns.find(x=>x.id===f.dataset.id);const result=transition(c,'editBrief',{brief:b});if(!result.ok){$('#form-errors').textContent=result.message;return;}ui.checks[c.id]={};}else{const id=`c-local-${state.serial++}`;state.campaigns.unshift(newCampaign(id,b));route={view:'campaign',id,tab:'brief'};}
    const id=f.dataset.id||route.id;ui.modal=null;closeModal();persist();go(`campaign/${id}/brief`);render();toast('Campaign brief saved.');
  }
  if(f.id==='content-form'){const c=state.campaigns.find(x=>x.id===f.dataset.id);const content=Object.fromEntries(fd);const result=transition(c,'saveContent',{content});if(!result.ok){$('#content-errors').textContent=result.message;return;}ui.checks[c.id]={};ui.modal=null;closeModal();persist();render();toast(result.message);}
  if(f.id==='return-form'){const c=state.campaigns.find(x=>x.id===f.dataset.id);const result=transition(c,'return',{note:fd.get('note')});if(!result.ok){$('#return-errors').textContent=result.message;return;}ui.checks[c.id]={};closeModal();persist();render();toast(result.message);}
});
let tick=0;
setInterval(()=>{tick++;let changed=false,relevant=false;for(const c of state.campaigns){let r;if(c.status==='preparing'&&tick%2===0)r=transition(c,'prepTick');if(c.status==='running'&&tick%2===0)r=transition(c,'sendTick');if(c.status==='retry_wait')r=transition(c,'retryTick');if(r?.ok){changed=true;if(route.view!=='campaign'||route.id===c.id||state.guide?.id===c.id)relevant=true;}}
  if(changed){persist();if(relevant)render();}
  const c=current();if(c?.status==='retry_wait'&&$('#retry-countdown'))$('#retry-countdown').textContent=Math.max(0,Math.ceil((c.delivery.retryAt-Date.now())/1000));
},600);
persist();render();
